#include <iostream>
#include <cstdio>
#include <cstring>
#include <queue>
#include <vector>
#include <cassert>
#include <cmath>
#include <string>
#include <algorithm>

using namespace std;

typedef long long ll;
typedef unsigned long long ull;
typedef long double ld;

const double EPS = 1e-9;
const double PI = acos(-1.0);
const int MOD = 1000000007;
const int INF = 2000000000;
const int MAXN = 210;
const int MAXM = 2 * MAXN * MAXN;
const int dx[] = {1, 0, 0, -1};
const int dy[] = {0, 1, -1, 0};
const int SRC = MAXN - 2;
const int DST = MAXN - 1;

inline int sq(int n) {
    return n * n;
}

struct Dinic {
    int to[MAXM];
    int flow[MAXM], cap[MAXM];
    int edgeIdx;

    vector <int> adj[MAXN];
    bool vis[MAXN];

    Dinic() : edgeIdx(0) { }

    void link(int u, int v, int c) {
        to[edgeIdx] = v;
        flow[edgeIdx] = 0;
        cap[edgeIdx] = c;
        adj[u].push_back(edgeIdx++);

        to[edgeIdx] = u;
        flow[edgeIdx] = 0;
        cap[edgeIdx] = 0;
        adj[v].push_back(edgeIdx++);
    }

    bool path(int node, int dest, int amt) {
        if (node == dest) return true;
        vis[node] = true;

        for (int i : adj[node]) {
            if (!vis[to[i]] && cap[i] - flow[i] >= amt && path(to[i], dest, amt)) {
                flow[i] += amt;
                flow[i ^ 1] -= amt;
                return true;
            }
        }
        return false;
    }

    int maxFlow(int src, int dst) {
        int amt = 1 << 30;
        int total = 0;

        while (amt > 0) {
            if (path(src, dst, amt)) {
                total += amt;
            } else {
                amt >>= 1;
            }
            memset(vis, false, sizeof vis);
        }
        return total;
    }
};

Dinic dinic;

int N, K;
char gridA[15][15];
char gridB[15][15];
int distMap[15][15];
bool visitedMap[15][15];

bool valid(int x, int y) {
    return 0 <= x && x < N &&
           0 <= y && y < N &&
           gridA[x][y] != 'Y' &&
           gridA[x][y] != 'Z';
}

void bfsFromZ(int sx, int sy) {
    for (int i = 0; i < N; ++i)
        for (int j = 0; j < N; ++j)
            distMap[i][j] = INF;

    queue<int> qx, qy;
    distMap[sx][sy] = 0;
    qx.push(sx);
    qy.push(sy);

    while (!qx.empty()) {
        assert(!qy.empty());
        int cx = qx.front(); qx.pop();
        int cy = qy.front(); qy.pop();

        for (int k = 0; k < 4; ++k) {
            int nx = cx + dx[k];
            int ny = cy + dy[k];
            if (valid(nx, ny) && distMap[nx][ny] == INF) {
                distMap[nx][ny] = distMap[cx][cy] + 1;
                qx.push(nx);
                qy.push(ny);
            }
        }
    }
}

void bfsFromSource(int sx, int sy) {
    queue<int> qx, qy, qlev;
    memset(visitedMap, false, sizeof visitedMap);

    visitedMap[sx][sy] = true;
    qx.push(sx);
    qy.push(sy);
    qlev.push(0);

    while (!qx.empty()) {
        assert(!qy.empty());
        int cx = qx.front(); qx.pop();
        int cy = qy.front(); qy.pop();
        int lev = qlev.front(); qlev.pop();

        if (isdigit(gridB[cx][cy]) && gridB[cx][cy] != '0') {
            dinic.link(sx * N + sy, sq(N) + 1 + cx * N + cy, INF);
        }

        if (lev >= K) continue;

        for (int k = 0; k < 4; ++k) {
            int nx = cx + dx[k];
            int ny = cy + dy[k];

            if (valid(nx, ny) && !visitedMap[nx][ny]) {
                if (distMap[nx][ny] > lev + 1) {
                    qx.push(nx);
                    qy.push(ny);
                    qlev.push(lev + 1);
                } else if (distMap[nx][ny] > lev && isdigit(gridB[nx][ny]) && gridB[nx][ny] != '0') {
                    dinic.link(sx * N + sy, sq(N) + 1 + nx * N + ny, INF);
                }
                visitedMap[nx][ny] = true;
            }
        }
    }
}

void buildNetwork() {
    int sx = -1, sy = -1;
    for (int i = 0; i < N && sx == -1; ++i)
        for (int j = 0; j < N && sx == -1; ++j)
            if (gridA[i][j] == 'Z') {
                sx = i; sy = j;
            }

    bfsFromZ(sx, sy);

    for (int i = 0; i < N; ++i)
        for (int j = 0; j < N; ++j)
            if (isdigit(gridA[i][j]) && gridA[i][j] != '0')
                dinic.link(SRC, i * N + j, gridA[i][j] - '0');

    for (int i = 0; i < N; ++i)
        for (int j = 0; j < N; ++j)
            if (isdigit(gridB[i][j]) && gridB[i][j] != '0')
                dinic.link(i * N + j + sq(N) + 1, DST, gridB[i][j] - '0');

    for (int i = 0; i < N; ++i)
        for (int j = 0; j < N; ++j)
            if (isdigit(gridA[i][j]) && gridA[i][j] != '0')
                bfsFromSource(i, j);
}

int main() {
#ifndef ONLINE_JUDGE
    freopen("in", "r", stdin);
#endif

    scanf("%d %d", &N, &K);
    scanf("\n");
    for (int i = 0; i < N; ++i) gets(gridA[i]);
    scanf("\n");
    for (int i = 0; i < N; ++i) gets(gridB[i]);

    buildNetwork();
    printf("%d\n", dinic.maxFlow(SRC, DST));

    return 0;
}
